   957→    fn update_data_column_subnets(&self, custody_group_count: u64) {
   958→        ServiceInboundMessage::UpdateEnrCgc(custody_group_count).send(&self.network_to_service_tx);
   959→
   960→        let node_id = self.network_globals.local_enr().node_id().raw();
   961→        let config = self.controller.chain_config();
   962→        let sampling_size = config.sampling_size_custody_groups(custody_group_count);
   963→
   964→        ServiceInboundMessage::UpdateDataColumnSubnets(sampling_size)
   965→            .send(&self.network_to_service_tx);
