   970→
   971→    fn update_sampling_columns(
   972→        controller: &RealController<P>,
   973→        raw_node_id: [u8; 32],
   974→        sampling_size: u64,
   975→        chain_config: &Config,
   976→    ) -> Result<()> {
   977→        let custody_groups = get_custody_groups(raw_node_id, sampling_size, chain_config)?;
   978→
   979→        let mut sampling_columns = HashSet::new();
   980→        for custody_index in custody_groups {
   981→            let columns = compute_columns_for_custody_group::<P>(custody_index, chain_config)?;
   982→            sampling_columns.extend(columns);
   983→        }
   984→        controller.on_store_sampling_columns(sampling_columns);
   985→
   986→        Ok(())
